function rehashManualTaskValue(value: Record<string, any>) {
  const { fingerprint: _fingerprint, ...payload } = value;
  value.fingerprint = `sha256-${createHash("sha256").update(JSON.stringify(stableTestValue(payload))).digest("hex")}`;
}

