test("T9-B2 refreshes disposition on storage focus reload and project switch without automatic writes", async ({ page }) => {
  test.setTimeout(180_000);
  await enterBuilderHome(page);
  await registerProjectDocumentForBrief(page, "ورودی پروژهٔ اول.pdf", "%PDF first project brief");
  await openLiveBriefFromHome(page);
  await expect(page.getByTestId("brief-input-item")).toContainText("ورودی پروژهٔ اول");
  await page.getByTestId("brief-back-button").click();
  const firstProjectId = await readActiveProjectId(page);
  await addAndActivateProject(page, "پروژهٔ دوم ورودی‌ها");
  await registerProjectDocumentForBrief(page, "ورودی پروژهٔ دوم.pdf", "%PDF second project brief");

  const beforeReadTriggers = await allLocalStorageBytes(page);
  await openLiveBriefFromHome(page);
  await expect(page.getByTestId("brief-input-item")).toContainText("ورودی پروژهٔ دوم");
  await expect(page.getByTestId("brief-inputs-section")).not.toContainText("ورودی پروژهٔ اول");
  await page.getByTestId("brief-back-button").click();
  expect(await allLocalStorageBytes(page)).toEqual(beforeReadTriggers);
  await dispatchBuilderStorageEvent(page, "chida-prototype-project-input-dispositions:v1", null, null);
  await page.evaluate(() => { window.dispatchEvent(new Event("blur")); window.dispatchEvent(new Event("focus")); });
  expect(await allLocalStorageBytes(page)).toEqual(beforeReadTriggers);
  await reloadIntoBuilderHome(page);
  await expect.poll(() => allLocalStorageBytes(page)).toEqual(beforeReadTriggers);

  const inputBytesBeforeSwitch = await page.evaluate(() => ({
    files: localStorage.getItem("chida-prototype-project-files:v1"),
    sources: localStorage.getItem("chida-prototype-project-sources:v1"),
    dispositions: localStorage.getItem("chida-prototype-project-input-dispositions:v1"),
  }));
  await activateExistingProjectFromHome(page, /برج نیلوفر/);
  expect(await readActiveProjectId(page)).toBe(firstProjectId);
  await openLiveBriefFromHome(page);
  await expect(page.getByTestId("brief-input-item")).toContainText("ورودی پروژهٔ اول");
  await expect(page.getByTestId("brief-inputs-section")).not.toContainText("ورودی پروژهٔ دوم");
  await page.getByTestId("brief-back-button").click();
  await activateExistingProjectFromHome(page, /پروژهٔ دوم ورودی‌ها/);
  await openLiveBriefFromHome(page);
  await expect(page.getByTestId("brief-input-item")).toContainText("ورودی پروژهٔ دوم");
  await expect(page.getByTestId("builder-home")).toHaveAttribute("data-project-brief-observation-status", "ready");
  const observedProjectInputHeads = await page.getByTestId("builder-home").getAttribute("data-project-brief-observation-heads");
  const projectInputFileIds = await page.evaluate(() => JSON.parse(localStorage.getItem("chida-prototype-project-files:v1") ?? "[]")
    .map((record: { id: string; displayName: string }) => ({ id: record.id, displayName: record.displayName })));
  const firstProjectInputId = projectInputFileIds.find((record: { displayName: string }) => record.displayName === "ورودی پروژهٔ اول.pdf")?.id;
  const secondProjectInputId = projectInputFileIds.find((record: { displayName: string }) => record.displayName === "ورودی پروژهٔ دوم.pdf")?.id;
  expect(firstProjectInputId).toEqual(expect.any(String));
  expect(secondProjectInputId).toEqual(expect.any(String));
  expect(observedProjectInputHeads).toContain(`project-input:project-document:${secondProjectInputId}`);
  expect(observedProjectInputHeads).not.toContain(`project-input:project-document:${firstProjectInputId}`);
  expect(await page.evaluate(() => ({
    files: localStorage.getItem("chida-prototype-project-files:v1"),
    sources: localStorage.getItem("chida-prototype-project-sources:v1"),
    dispositions: localStorage.getItem("chida-prototype-project-input-dispositions:v1"),
  }))).toEqual(inputBytesBeforeSwitch);
  expect(await page.evaluate(() => localStorage.getItem("chida-prototype-project-input-dispositions:v1"))).toBeNull();
});

test("T9-B2 shows the scoped unavailable section for terminal File Source and recovery failures", async ({ page }) => {
  test.setTimeout(180_000);
  await page.setViewportSize({ width: 390, height: 844 });
  await enterBuilderHome(page);
  const storageKeys = {
    files: "chida-prototype-project-files:v1",
    sources: "chida-prototype-project-sources:v1",
    intent: "chida-prototype-project-sources:v1:intake-intent:v1",
  } as const;
  const baseline = await page.evaluate((keys) => Object.fromEntries(Object.entries(keys).map(([name, key]) => [name, localStorage.getItem(key)])), storageKeys);
  const cases = [
    { name: "malformed File", key: storageKeys.files, value: "{malformed-file" },
    { name: "malformed Source", key: storageKeys.sources, value: "{malformed-source" },
    { name: "recovery blocked", key: storageKeys.intent, value: "{malformed-intake-intent" },
  ];

  for (const fixture of cases) {
    await page.evaluate(({ keys, saved, active }) => {
      for (const [name, key] of Object.entries(keys)) {
        const value = saved[name];
        if (value === null) localStorage.removeItem(key);
        else localStorage.setItem(key, value);
      }
      localStorage.setItem(active.key, active.value);
    }, { keys: storageKeys, saved: baseline, active: fixture });
    await reloadIntoBuilderHome(page);
    await openLiveBriefFromHome(page);
    const section = page.getByTestId("brief-inputs-section");
    await expect(section, fixture.name).toHaveAttribute("data-status", "unavailable", { timeout: 20_000 });
    await expect(section, fixture.name).toContainText("اطلاعات اسناد و ورودی‌ها در دسترس نیست؛ وضعیت قبلی دست‌نخورده ماند.");
    await expect(section, fixture.name).not.toContainText("در حال بررسی فایل‌ها و ورودی‌های ثبت‌شده");
    await expect(page.getByTestId("builder-home"), `${fixture.name} observation`).toHaveAttribute("data-project-brief-observation-status", "unavailable");
    await expect(page.getByTestId("builder-home"), `${fixture.name} observation heads`).toHaveAttribute("data-project-brief-observation-heads", "");
    await expect(page.getByTestId("brief-decisions-section"), fixture.name).toContainText("تصمیمی منتظر شما نیست");
    await expect(page.getByTestId("brief-tasks-section"), fixture.name).toContainText("کار بازی در این پروژه نیست");
    await expect(page.getByTestId("brief-procurement-section"), fixture.name).toContainText("درخواست بازی در این پروژه نیست");
    await page.getByTestId("brief-back-button").click();
  }
});

