  await page.evaluate(({ legacyKey, legacyRaw }) => window.localStorage.setItem(legacyKey, legacyRaw), {
    legacyKey: bgF4ApprovalLegacyStorageKey,
    legacyRaw: fixture.approvalRaw,
  });
  await page.reload();
